INSERT INTO t_subject (id, name, short_name, type, sort, regular_sort, motto, proc_h_min, proc_h_max, proc_h_step, proc_w_max) VALUES
(1, '语文', NULL, '国家课程', 1, 1, '博观而约取，厚积而薄发。 ——苏轼 箴言：学习之道，在于坚持和寻找正确的方法。', -10, 50, 10, 4),
(2, '数学', NULL, '国家课程', 2, 2, '业精于勤，荒于嬉，行成于思，毁于随。 译文：学业的精深在于勤奋刻苦，荒废在于嬉戏游乐；道德行为的成功在于深思熟虑，败毁在于因循苟且。 ——韩愈《进学解》', -10, 30, 5, 3),
(3, '英语', NULL, '国家课程', 3, 3, '非学无以广才，非志无以成学。 译文：不学习便无法增长才于，没有志向就难于取得学业上的成功。 ——《诸葛亮集•诫子书》', -10, 50, 10, 3),
(4, '道德与法治', '政治', '国家课程', 8, 4, '饭疏食，饮水，曲肱而枕之，乐亦在其中矣。不义而富且贵，于我如浮云。 ——《论语》 箴言：财富如浮云，生不带来，死不带去，真正留下的，是我们对这个世界的贡献。', -4, 8, 2, 1.2),
(5, '历史', NULL, '国家课程', 4, 5, '以铜为镜，可以正衣冠；以古为镜，可以知兴替；以人为镜，可以明得失。 ——《旧唐书·魏征列传》 箴言：前进的路上，要不断反思、关照自己的不足，学习更多东西，更进一步。', -2, 8, 2, 1.2),
(6, '地理', NULL, '国家课程', 6, 6, '乐民之乐者，民亦乐其乐；忧民之忧者，民亦忧其忧。 ——《孟子》 箴言：做领导，要能体恤下属，一味打压，则尽失民心。', -20, 40, 10, 12),
(7, '生物', NULL, '国家课程', 7, 7, '学和行本来是有机联着的，学了必须要想，想通了就要行，要在行的当中才能看出自己是否真正学到了手。否则读书虽多，只是成为一座死书库。 ——谢觉哉《青年人要努力学习》', -3, 15, 3, 1.2),
(8, '物理', NULL, '国家课程', 5, 8, '老当益壮，宁移白首之心；穷且益坚，不坠青云之志。 ——唐·王勃 箴言：老去的只是身体，心灵可以永远保持丰盛。', -3, 15, 3, 1.2),
(9, '体育', NULL, '国家课程', 12, 9, NULL, NULL, NULL, NULL, NULL),
(10, '音乐', NULL, '国家课程', 10, 10, '人品、学问，俱成于志气；无志气人，一事做不得。 译文：一个人之所以具有高尚的品德，渊博的学问，都是由于他有志气；没有志气的人，什么事也做不成。 ——（清）申居郧《西岩赘语》', -1, 6, 1, 1.2),
(11, '信息技术', '信息', '国家课程', 9, 11, '为天地立心，为生民立命，为往圣继绝学，为万世开太平。 ---张载 立千古大志，乃是圣人也。', -0.5, 2.5, 0.5, 1.2),
(12, '美术', NULL, '国家课程', 11, 12, '勿以恶小而为之，勿以善小而不为。 ——刘备 箴言：越是微小的事情，越见品质。', -0.6, 1.8, 0.3, 1.2);
