INSERT INTO t_comment (student_id, term_id, type, content, ai_draft, status) VALUES
(1, 2, '班主任', '“百舸争流，奋楫者先；中流击水，勇进者胜。” 小华，你聪明上进，是老师心目中的好学生。学习上，你自觉性很高，总能超前预习，所以学习时毫不费劲。这学期，你的成绩也有了很大的进步。作为值日班长，本学期在班级管理上有些松懈，老师希望你在班级工作上能够更加用心一点，做老师的得力助手。加油！', NULL, '已确认'),
